function BeginnerAssembleBossPanel:Refresh(config)
	self.config = config
	self.dojo = BeginnerUtils.GetBeginnerDojo()
	self:FillRoleBuffInfo()
	self:RefreshBossName()
	self:RefreshPlayerRank()
