function BeginnerAssembleBossPanel:RefreshRedPoint()
	local isHaveReward = BeginnerUtils.GetBeginnerMgr():IsCanOneKeyDrawReward()
	CfUtils.SetActive(self.BtnHurtReward.transform:Find("redPoint"), isHaveReward)
end

function BeginnerAssembleBossPanel:RefreshBossName()
	local lineUpInfo = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.dojo:GetBossQuestId())
	for _, line in ipairs(lineUpInfo) do
		local ids = line.wave1NpcId
		for index, id in ipairs(ids) do
			local vo = CardConfMgr:GetInstance():GetMonsterTypeVoById(id)
			if checkNumber(vo.monsterClass) == Constants.RoleClass.Boss then
				local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(vo.skinId)
				CfUtils.FillText(self.TxtName, skinVo.name)
			end
		end
	end
end

function BeginnerAssembleBossPanel:FillRoleBuffInfo()
	local upGroup = self.dojo:GetRoleBuffInfo()
	UICommonUtils.RefreshCommonUpGroup(self.CommRoleBonusLayoutGroup,upGroup, false,{{
																								   id = Constants.UITypeIds.BeginnerAssembleMainDialog
																							   }})
end

function BeginnerAssembleBossPanel:RefreshTopGoods()
