function BeginnerAssembleBossPanel:OnBtnFontStyleClick()
	CfUtils.DialogOpen(Constants.UITypeIds.UIFightTeamChoose, {
																levelId = self.dojo:GetBossQuestId(), upBuffData = self:GetUpBuffData(),upGroup = self.dojo:GetRoleBuffInfo() }, { { id = Constants.UITypeIds.BeginnerAssembleMainDialog } })
end

function BeginnerAssembleBossPanel:GetUpBuffData()
	local data = {}
	---@type CardComponent
	local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
	local upGroup = self.dojo:GetRoleBuffInfo()
	for i, v in ipairs(upGroup) do
		local hasCard = cardComp:IsHasCard(v.refId)
		local tempData = {}
		tempData.refId = v.refId
		tempData.type = v.type
		local index = 1
		if hasCard then
			local cardDojo = cardComp:GetCardByConfId(v.refId)
			local star = cardDojo.star
			index = star + 1
		
		end
		tempData.commonAddId = v.additions[index].commonAddId
		table.insert(data,tempData)
	end
	return data
end

function BeginnerAssembleBossPanel:RefreshTimeShow()
	local curTime = GameUtils.GetServerTime() or os.time()
	local time =  math.max(0,self.dojo.bossLeftSeconds - curTime)
	CfUtils.FillText(self.TextTime2,CfUtils.GetTimeHMS4(time))
end

function BeginnerAssembleBossPanel:OnBtnHurtRewardClick()
