		rankType = 1, entryMgr = BeginnerUtils.GetBeginnerMgr()
	})
end

function BeginnerAssembleBossPanel:OnBtnCheckClick()
	local bossId = self.dojo:GetBossQuestId()
	local levelVo = CfUtils.GetCfVo(AutoIds.IdSetting8924, "BeginnerBossQuestVo", bossId)
	CfUtils.DialogOpen(Constants.UITypeIds.CommonBossDetailsDialog, { planVo = { bossId = bossId, modelId = levelVo.modelId }, questVo = levelVo }, { { id = Constants.UITypeIds.BeginnerAssembleMainDialog } })
end

